<?php
namespace Xdecaro\Component\Decarofinance\Administrator\View\Deposits;
defined('_JEXEC') or die;
use Joomla\CMS\Factory; use Joomla\CMS\Language\Text; use Joomla\CMS\MVC\View\HtmlView as BaseHtmlView; use Joomla\CMS\Toolbar\ToolbarHelper;
final class HtmlView extends BaseHtmlView { public array $items=[]; public array $organizations=[]; public array $people=[]; public function display($tpl=null):void { if(!Factory::getApplication()->getIdentity()->authorise('core.manage','com_decarofinance')) throw new \RuntimeException(Text::_('JERROR_ALERTNOAUTHOR'),403); ToolbarHelper::title(Text::_('COM_DECAROFINANCE_DEPOSITS'),'credit'); \Xdecaro\Component\Decarofinance\Administrator\Helper\UiHelper::loadAssets(); $component=Factory::getApplication()->bootComponent('com_decarofinance'); if(!$component instanceof \Xdecaro\Component\Decarofinance\Administrator\Extension\DecarofinanceComponent) throw new \RuntimeException('Finance component is unavailable.'); $references=$component->getReferenceLookupService(); $this->items=$component->getFinanceQueryService()->listDepositAccounts(); foreach($this->items as &$item){$item['owner_label']=$references->label($item['owner_component']??null,$item['owner_entity']??null,$item['owner_id']??null);} unset($item); $this->organizations=$references->listOrganizations(); $this->people=$references->listPeople(); parent::display($tpl); } }
